ee:message.ee:set-payload:
%dw 2.0
output multipart/form-data boundary="--------------135678"

var fileName = vars.FullFileName default "Bill.pdf"
var extension = lower(vars.FileExtension default (fileName splitBy ".")[-1] default "pdf")

var mimeType = extension match {
    case "pdf"  -> "application/pdf"
    case "png"  -> "image/png"
    case "jpg"  -> "image/jpeg"
    case "jpeg" -> "image/jpeg"
    case "doc"  -> "application/msword"
    case "docx" -> "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    case "xls"  -> "application/vnd.ms-excel"
    case "xlsx" -> "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    case "txt"  -> "text/plain"
    else        -> "application/octet-stream"
}
---
{
    parts: {
        file: {
            headers: {
                "Content-Disposition": {
                    name: "file",
                    filename: fileName,
                    subtype: "form-data"
                },
                "Content-Type": mimeType
            },
            // Fallback to payload if vars.File is null
            content: vars.File default payload
        }
    }
}

%dw 2.0
output application/java
---
{
    Matter__c: vars.matterId default null,
    Source_File_Name__c: (vars.idpResult.documentName default vars.FullFileName) default null,
    // Unique external id, so a later extraction callback can be matched back
    // to this exact package.
    Correlation_Id__c: correlationId,
    Status__c:
        if ((vars.idpResult.status default "") == "SUCCEEDED") "In Review"
        else "Failed"
}

%dw 2.0
output application/java

var fieldSrc = vars.idpResult.fields default {}
var tableSrc = vars.idpResult.tables default {}

var docCategory = fieldSrc.document_category.value

// Pull one attribute off every cell of every row of a table, dropping nulls.
fun cellsOf(rows, sel) =
    (((rows default []) flatMap ((row) -> row pluck ((c, ck) -> sel(c)))) filter ($ != null))

// Min confidence and page span cover standalone fields AND table cells, since
// there is no child object left to roll either up from natively.
var allConfidences =
    ((fieldSrc pluck ((v, k) -> v.confidenceScore)) filter ($ != null))
    ++ flatten(tableSrc pluck ((rows, tKey) -> cellsOf(rows, (c) -> c.confidenceScore)))

var allPages =
    ((fieldSrc pluck ((v, k) -> v.pageNumber)) filter ($ != null))
    ++ flatten(tableSrc pluck ((rows, tKey) -> cellsOf(rows, (c) -> c.pageNumber)))
---
{
    Package__c: vars.idpPackageId,
    // Hardcoded to the IDP_File_Option__mdt DeveloperName, confirmed live 2026-09-28:
    // uppercase PHARMACY, one of 23 records (BILL, LETTER, POLICE_REPORT, ...). This
    // endpoint only ever produces pharmacy bills, and the code is what the routing API
    // dispatches on after review, so it must not vary with whatever label IDP happens to
    // return in document_category. Keep it in step with that metadata type if renamed.
    Document_Type_Code__c: "PHARMACY",
    Document_Type_Label__c: (docCategory default p('idp.documentTypeLabel')) as String,
    Extracted_Data_Json__c: write(vars.idpResult, "application/json", {"indent": false}),
    Min_Field_Confidence__c: if (isEmpty(allConfidences)) null else min(allConfidences),
    Page_Start__c: if (isEmpty(allPages)) null else min(allPages),
    Page_End__c: if (isEmpty(allPages)) null else max(allPages)
}
